import AppKit
import ChopCore

@MainActor
final class AppDelegate: NSObject, NSApplicationDelegate, NSMenuItemValidation {
  private var workspaceWindow: WorkspaceWindowController? { windowManager.active }
  private lazy var windowManager = WorkspaceWindowManager(engine: engine)
  private lazy var projectLibrary = ProjectLibraryController(
    manager: windowManager,
    store: ProjectLibraryStore(
      fileURL: FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        .appendingPathComponent("Chop/projects.json")))
  private var projectPanel: NSOpenPanel?
  private let engine = TerminalEngine()
  private let session = SessionCoordinator(
    store: SessionStore(
      fileURL:
        FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        .appendingPathComponent("Chop/session.json")))

  func applicationDidFinishLaunching(_ notification: Notification) {
    NSApp.setActivationPolicy(.regular)
    let mode = AppearanceMode.load()
    NSApp.appearance = mode.appearance
    do {
      try engine.start(appearanceMode: mode)
    } catch {
      let alert = NSAlert()
      alert.messageText = error.localizedDescription
      alert.addButton(withTitle: "종료")
      alert.runModal()
      NSApp.terminate(nil)
      return
    }
    configureMainMenu()
    projectLibrary.load()
    let saved = session.load()
    windowManager.onAppearanceChangeRequested = { [weak self] mode in self?.applyAppearance(mode) }
    if let saved, !saved.windows.isEmpty {
      for snapshot in saved.windows {
        windowManager.open(
          snapshot: snapshot, legacyDefaults: session.migratedLegacyWorkspace ? .standard : nil,
          recordVisit: false)
      }
      if let id = saved.focusedWindowID { windowManager.activate(id) }
    } else {
      windowManager.open()
    }
    session.attach(windowManager)
    session.saveNow()
    NSApp.activate(ignoringOtherApps: true)
  }

  func applicationShouldHandleReopen(
    _ sender: NSApplication,
    hasVisibleWindows flag: Bool
  ) -> Bool {
    if !flag {
      if let existing = windowManager.active {
        windowManager.activate(existing.id)
      } else {
        newWindow()
      }
    }
    return true
  }

  @objc private func newWindow() {
    windowManager.open(directory: workspaceWindow?.pane.workingDirectory)
    NSApp.activate(ignoringOtherApps: true)
  }

  @objc private func openProjectWindow() {
    guard projectPanel == nil else { return }
    let panel = NSOpenPanel()
    projectPanel = panel
    panel.title = "프로젝트 폴더에서 새 윈도우"
    panel.prompt = "열기"
    panel.canChooseDirectories = true
    panel.canChooseFiles = false
    panel.allowsMultipleSelection = false
    panel.canCreateDirectories = false
    panel.directoryURL = workspaceWindow?.content.fileBrowser.rootURL
    let completion: (NSApplication.ModalResponse) -> Void = { [weak self] response in
      self?.projectPanel = nil
      guard response == .OK, let self, let url = panel.url else { return }
      windowManager.open(directory: url.standardizedFileURL.path)
      NSApp.activate(ignoringOtherApps: true)
    }
    if let window = workspaceWindow?.window, window.attachedSheet == nil {
      panel.beginSheetModal(for: window, completionHandler: completion)
    } else {
      panel.begin(completionHandler: completion)
    }
  }

  @objc private func cloneProject() { windowManager.requestClone() }

  func applicationDockMenu(_ sender: NSApplication) -> NSMenu? {
    let menu = NSMenu()
    for (title, action) in [
      ("새 윈도우", #selector(newWindow)),
      ("프로젝트 폴더에서 새 윈도우…", #selector(openProjectWindow)),
    ] {
      let item = menu.addItem(withTitle: title, action: action, keyEquivalent: "")
      item.target = self
    }
    return menu
  }

  func applicationShouldTerminate(_ sender: NSApplication) -> NSApplication.TerminateReply {
    if windowManager.needsConfirmClose || windowManager.isCloningProject {
      let alert = NSAlert()
      alert.messageText = "Chop을 종료할까요?"
      alert.informativeText =
        windowManager.isCloningProject
        ? "실행 중인 터미널 작업과 프로젝트 클론이 종료됩니다."
        : "실행 중인 터미널 작업이 종료됩니다."
      alert.addButton(withTitle: "취소")
      alert.addButton(withTitle: "종료")
      if alert.runModal() != .alertSecondButtonReturn { return .terminateCancel }
    }
    guard session.confirmTerminationIfUnsaved() else { return .terminateCancel }
    if windowManager.isCloningProject {
      windowManager.prepareToTerminate()
      Task {
        await windowManager.cancelClonesForTermination()
        sender.reply(toApplicationShouldTerminate: true)
      }
      return .terminateLater
    }
    return .terminateNow
  }

  func applicationWillTerminate(_ notification: Notification) {
    session.prepareToTerminate()
    windowManager.shutdown()
    engine.shutdown()
  }

  @objc private func openTerminal() { workspaceWindow?.workspace.addTerminal() }
  @objc private func openWebPage() { workspaceWindow?.workspace.addWebPage() }
  @objc private func focusWebAddress() { workspaceWindow?.pane.browser?.focusAddress() }
  @objc private func reloadWebPage() { workspaceWindow?.pane.browser?.reload() }
  @objc private func webBack() { workspaceWindow?.pane.browser?.goBack() }
  @objc private func webForward() { workspaceWindow?.pane.browser?.goForward() }
  @objc private func webZoomIn() { workspaceWindow?.pane.browser?.changeZoom(by: 0.25) }
  @objc private func webZoomOut() { workspaceWindow?.pane.browser?.changeZoom(by: -0.25) }
  @objc private func webResetZoom() { workspaceWindow?.pane.browser?.resetZoom() }
  @objc private func openWebInBrowser() { workspaceWindow?.pane.browser?.openInBrowser() }
  @objc private func closeTerminal() { workspaceWindow?.workspace.requestCloseFocused() }
  @objc private func splitRight() { workspaceWindow?.workspace.splitRight() }
  @objc private func splitDown() { workspaceWindow?.workspace.splitDown() }
  @objc private func toggleLayoutEditing() { workspaceWindow?.workspace.toggleEditing() }
  @objc private func focusLeft() { workspaceWindow?.workspace.moveFocus(.left) }
  @objc private func focusRight() { workspaceWindow?.workspace.moveFocus(.right) }
  @objc private func focusUp() { workspaceWindow?.workspace.moveFocus(.up) }
  @objc private func focusDown() { workspaceWindow?.workspace.moveFocus(.down) }
  @objc private func swapLeft() { workspaceWindow?.workspace.swapFocusedPane(.left) }
  @objc private func swapRight() { workspaceWindow?.workspace.swapFocusedPane(.right) }
  @objc private func swapUp() { workspaceWindow?.workspace.swapFocusedPane(.up) }
  @objc private func swapDown() { workspaceWindow?.workspace.swapFocusedPane(.down) }
  @objc private func toggleZoom() { workspaceWindow?.workspace.toggleZoom() }
  @objc private func renamePane() { workspaceWindow?.workspace.requestRename() }
  @objc private func retrySave() { session.retrySave() }
  @objc private func toggleFileTree() { workspaceWindow?.content.toggleFileTree() }
  @objc private func chooseFileTreeFolder() {
    workspaceWindow?.content.showFileTree()
    guard workspaceWindow?.content.isFileTreeVisible == true else { return }
    workspaceWindow?.content.fileBrowser.chooseFolder()
  }

  @objc private func chooseAppearance(_ sender: NSMenuItem) {
    guard let value = sender.representedObject as? String,
      let mode = AppearanceMode(rawValue: value)
    else { return }
    applyAppearance(mode)
  }

  private func applyAppearance(_ mode: AppearanceMode) {
    engine.applyAppearance(mode)
    NSApp.appearance = mode.appearance
    windowManager.applyAppearance(mode)
    mode.save()
  }

  func validateMenuItem(_ menuItem: NSMenuItem) -> Bool {
    if menuItem.action == #selector(newWindow) { return true }
    if menuItem.action == #selector(openProjectWindow) { return projectPanel == nil }
    if menuItem.action == #selector(cloneProject) { return true }
    if menuItem.action == #selector(chooseAppearance(_:)) {
      menuItem.state =
        (menuItem.representedObject as? String) == engine.appearanceMode.rawValue ? .on : .off
      return true
    }
    guard let workspace = workspaceWindow?.workspace, workspaceWindow?.window?.isVisible == true
    else { return false }
    switch menuItem.action {
    case #selector(openTerminal): return workspace.canAddTerminal
    case #selector(openWebPage): return workspace.canAddTerminal
    case #selector(focusWebAddress), #selector(reloadWebPage), #selector(webZoomIn),
      #selector(webZoomOut), #selector(webResetZoom), #selector(openWebInBrowser):
      return workspace.focusedPane.browser != nil
    case #selector(webBack): return workspace.focusedPane.browser?.canGoBack == true
    case #selector(webForward): return workspace.focusedPane.browser?.webView.canGoForward == true
    case #selector(toggleFileTree):
      menuItem.title =
        workspaceWindow?.content.isFileTreeVisible == true
        ? "파일 트리 숨기기" : "파일 트리 보기"
      return true
    case #selector(splitRight): return workspace.canSplit(workspace.focusedID, axis: .horizontal)
    case #selector(splitDown): return workspace.canSplit(workspace.focusedID, axis: .vertical)
    case #selector(toggleZoom): return workspace.focusedPane.canZoom
    case #selector(swapLeft): return workspace.canSwapFocusedPane(.left)
    case #selector(swapRight): return workspace.canSwapFocusedPane(.right)
    case #selector(swapUp): return workspace.canSwapFocusedPane(.up)
    case #selector(swapDown): return workspace.canSwapFocusedPane(.down)
    case #selector(closeTerminal):
      menuItem.title =
        workspace.isTabbed
        ? "탭 닫기"
        : workspace.focusedPane.browser != nil
          ? "웹사이트 닫기"
          : workspace.focusedPane.isRunning ? "터미널 닫기" : "빈 칸 제거"
      return workspace.focusedPane.isRunning || workspace.layout.paneIDs.count > 1
    default: return true
    }
  }

  private func configureMainMenu() {
    let mainMenu = NSMenu()

    let applicationItem = NSMenuItem()
    let applicationMenu = NSMenu(title: "Chop")
    applicationMenu.addItem(
      withTitle: "Chop에 관하여",
      action: #selector(NSApplication.orderFrontStandardAboutPanel(_:)),
      keyEquivalent: ""
    )
    applicationMenu.addItem(.separator())
    applicationMenu.addItem(
      withTitle: "Chop 가리기",
      action: #selector(NSApplication.hide(_:)),
      keyEquivalent: "h"
    )
    applicationMenu.addItem(.separator())
    applicationMenu.addItem(
      withTitle: "Chop 종료",
      action: #selector(NSApplication.terminate(_:)),
      keyEquivalent: "q"
    )
    applicationItem.submenu = applicationMenu
    mainMenu.addItem(applicationItem)

    let fileItem = NSMenuItem()
    let fileMenu = NSMenu(title: "파일")
    let new = fileMenu.addItem(withTitle: "새 윈도우", action: #selector(newWindow), keyEquivalent: "n")
    new.target = self
    let project = fileMenu.addItem(
      withTitle: "프로젝트 폴더에서 새 윈도우…", action: #selector(openProjectWindow), keyEquivalent: "n")
    project.keyEquivalentModifierMask = [.command, .shift]
    project.target = self
    let clone = fileMenu.addItem(
      withTitle: "GitHub 프로젝트 클론…", action: #selector(cloneProject), keyEquivalent: "")
    clone.target = self
    projectLibrary.install(in: fileMenu)
    fileItem.submenu = fileMenu
    mainMenu.addItem(fileItem)

    let terminalItem = NSMenuItem()
    let terminalMenu = NSMenu(title: "터미널")
    let open = terminalMenu.addItem(
      withTitle: "터미널 추가", action: #selector(openTerminal), keyEquivalent: "t")
    open.target = self
    let close = terminalMenu.addItem(
      withTitle: "터미널 닫기", action: #selector(closeTerminal), keyEquivalent: "w")
    close.target = self
    terminalMenu.addItem(.separator())
    for (title, action, key, modifiers) in [
      ("오른쪽으로 나누기", #selector(splitRight), "d", NSEvent.ModifierFlags.command),
      ("아래로 나누기", #selector(splitDown), "d", [.command, .shift]),
      ("레이아웃 편집", #selector(toggleLayoutEditing), "l", [.command, .shift]),
      ("칸 확대·복귀", #selector(toggleZoom), "\r", [.command, .shift]),
      ("칸 이름 바꾸기…", #selector(renamePane), "r", [.command, .shift]),
      ("레이아웃 다시 저장", #selector(retrySave), "", []),
      (
        "왼쪽 칸으로 이동", #selector(focusLeft), String(UnicodeScalar(NSLeftArrowFunctionKey)!),
        [.command, .option]
      ),
      (
        "오른쪽 칸으로 이동", #selector(focusRight), String(UnicodeScalar(NSRightArrowFunctionKey)!),
        [.command, .option]
      ),
      (
        "위 칸으로 이동", #selector(focusUp), String(UnicodeScalar(NSUpArrowFunctionKey)!),
        [.command, .option]
      ),
      (
        "아래 칸으로 이동", #selector(focusDown), String(UnicodeScalar(NSDownArrowFunctionKey)!),
        [.command, .option]
      ),
      (
        "왼쪽 칸과 자리 바꾸기", #selector(swapLeft), String(UnicodeScalar(NSLeftArrowFunctionKey)!),
        [.command, .option, .shift]
      ),
      (
        "오른쪽 칸과 자리 바꾸기", #selector(swapRight), String(UnicodeScalar(NSRightArrowFunctionKey)!),
        [.command, .option, .shift]
      ),
      (
        "위 칸과 자리 바꾸기", #selector(swapUp), String(UnicodeScalar(NSUpArrowFunctionKey)!),
        [.command, .option, .shift]
      ),
      (
        "아래 칸과 자리 바꾸기", #selector(swapDown), String(UnicodeScalar(NSDownArrowFunctionKey)!),
        [.command, .option, .shift]
      ),
    ] {
      let item = terminalMenu.addItem(withTitle: title, action: action, keyEquivalent: key)
      item.target = self
      item.keyEquivalentModifierMask = modifiers
    }
    terminalItem.submenu = terminalMenu
    mainMenu.addItem(terminalItem)

    let webItem = NSMenuItem()
    let webMenu = NSMenu(title: "웹사이트")
    for (title, action, key, modifiers) in [
      ("새 칸에서 웹사이트 열기", #selector(openWebPage), "b", NSEvent.ModifierFlags([.command, .shift])),
      ("주소 입력", #selector(focusWebAddress), "l", .command),
      ("새로고침", #selector(reloadWebPage), "r", .command),
      ("뒤로", #selector(webBack), "[", .command),
      ("앞으로", #selector(webForward), "]", .command),
      ("웹페이지 확대", #selector(webZoomIn), "=", .command),
      ("웹페이지 축소", #selector(webZoomOut), "-", .command),
      ("웹페이지 원래 크기", #selector(webResetZoom), "0", .command),
      ("브라우저에서 열기", #selector(openWebInBrowser), "", .command),
    ] {
      let item = webMenu.addItem(withTitle: title, action: action, keyEquivalent: key)
      item.target = self
      item.keyEquivalentModifierMask = modifiers
    }
    webItem.submenu = webMenu
    mainMenu.addItem(webItem)

    let editItem = NSMenuItem()
    let editMenu = NSMenu(title: "편집")
    editMenu.addItem(withTitle: "복사", action: #selector(TerminalView.copy(_:)), keyEquivalent: "c")
    editMenu.addItem(
      withTitle: "붙여넣기", action: #selector(TerminalView.paste(_:)), keyEquivalent: "v")
    editMenu.addItem(
      withTitle: "전체 선택", action: #selector(TerminalView.selectAll(_:)), keyEquivalent: "a")
    editMenu.addItem(.separator())
    for (title, action, key, modifiers) in [
      (
        "한 페이지 위로", #selector(TerminalView.scrollPageUp(_:)),
        String(UnicodeScalar(NSPageUpFunctionKey)!), NSEvent.ModifierFlags.shift
      ),
      (
        "한 페이지 아래로", #selector(TerminalView.scrollPageDown(_:)),
        String(UnicodeScalar(NSPageDownFunctionKey)!), .shift
      ),
      (
        "맨 위로 스크롤", #selector(TerminalView.scrollToTop(_:)),
        String(UnicodeScalar(NSUpArrowFunctionKey)!), .command
      ),
      (
        "맨 아래로 스크롤", #selector(TerminalView.scrollToBottom(_:)),
        String(UnicodeScalar(NSDownArrowFunctionKey)!), .command
      ),
    ] {
      let item = editMenu.addItem(withTitle: title, action: action, keyEquivalent: key)
      item.keyEquivalentModifierMask = modifiers
    }
    editItem.submenu = editMenu
    mainMenu.addItem(editItem)

    let viewItem = NSMenuItem()
    let viewMenu = NSMenu(title: "보기")
    for mode in AppearanceMode.allCases {
      let item = viewMenu.addItem(
        withTitle: mode.title, action: #selector(chooseAppearance(_:)), keyEquivalent: "")
      item.target = self
      item.representedObject = mode.rawValue
    }
    viewMenu.addItem(.separator())
    let fileTree = viewMenu.addItem(
      withTitle: "파일 트리 보기", action: #selector(toggleFileTree), keyEquivalent: "e")
    fileTree.keyEquivalentModifierMask = [.command, .shift]
    fileTree.target = self
    let folder = viewMenu.addItem(
      withTitle: "폴더 선택…", action: #selector(chooseFileTreeFolder), keyEquivalent: "o")
    folder.target = self
    viewItem.submenu = viewMenu
    mainMenu.addItem(viewItem)

    let windowItem = NSMenuItem()
    let windowMenu = NSMenu(title: "윈도우")
    windowMenu.addItem(
      withTitle: "최소화",
      action: #selector(NSWindow.performMiniaturize(_:)),
      keyEquivalent: "m"
    )
    let closeWindow = windowMenu.addItem(
      withTitle: "닫기",
      action: #selector(NSWindow.performClose(_:)),
      keyEquivalent: "w"
    )
    closeWindow.keyEquivalentModifierMask = [.command, .shift]
    windowItem.submenu = windowMenu
    mainMenu.addItem(windowItem)

    NSApp.mainMenu = mainMenu
    NSApp.windowsMenu = windowMenu
  }
}

import AppKit
import ChopCore

@MainActor
final class ProjectLibraryController: NSObject, NSMenuDelegate, NSMenuItemValidation {
  let recentMenu = NSMenu(title: "최근 프로젝트")
  let configurationMenu = NSMenu(title: "작업 구성")
  private let manager: WorkspaceWindowManager
  private let store: ProjectLibraryStore
  private(set) var library = ProjectLibrary()
  private var loadFailed = false
  private var reportedVisitFailure = false

  init(manager: WorkspaceWindowManager, store: ProjectLibraryStore) {
    self.manager = manager
    self.store = store
    super.init()
    recentMenu.delegate = self
    configurationMenu.delegate = self
    manager.onProjectOpened = { [weak self] path in self?.recordVisit(path) }
  }

  func install(in menu: NSMenu) {
    for submenu in [recentMenu, configurationMenu] {
      let item = menu.addItem(withTitle: submenu.title, action: nil, keyEquivalent: "")
      item.submenu = submenu
      menuNeedsUpdate(submenu)
    }
  }

  func load(reportFailure: Bool = true) {
    do {
      library = try store.load()
      loadFailed = false
      reportedVisitFailure = false
    } catch {
      loadFailed = true
      if reportFailure { show(error, title: "프로젝트 기록을 불러오지 못했어요") }
    }
  }

  private func recordVisit(_ path: String) {
    do {
      library = try store.update { try $0.visit(path) }
      reportedVisitFailure = false
    } catch {
      guard !reportedVisitFailure else { return }
      reportedVisitFailure = true
      show(error, title: "최근 프로젝트를 저장하지 못했어요")
    }
  }

  func menuNeedsUpdate(_ menu: NSMenu) {
    menu.removeAllItems()
    if menu === recentMenu {
      for path in library.recentProjects {
        let item = add(
          recentTitle(path), to: menu,
          action: #selector(openRecent(_:)))
        item.representedObject = path
        item.toolTip = path
      }
      if library.recentProjects.isEmpty {
        placeholder(loadFailed ? "프로젝트 기록을 읽지 못했어요" : "최근 프로젝트가 없어요", in: menu)
      }
      menu.addItem(.separator())
      add("목록 지우기", to: menu, action: #selector(clearRecent))
    } else {
      let save = add("현재 구성 저장…", to: menu, action: #selector(saveCurrent))
      save.keyEquivalent = "s"
      save.keyEquivalentModifierMask = [.command, .shift]
      menu.addItem(.separator())
      let entries = manager.active.map { library.configurations(for: $0.projectDirectory) } ?? []
      if entries.isEmpty { placeholder("저장한 구성이 없어요", in: menu) }
      for entry in entries {
        let item = add(entry.name, to: menu, action: #selector(openConfiguration(_:)))
        item.representedObject = entry.id.uuidString
        item.toolTip = "새 윈도우에서 열기 — \(entry.projectDirectory)"
      }
      menu.addItem(.separator())
      add("구성 삭제…", to: menu, action: #selector(deleteConfiguration))
    }
    if loadFailed {
      menu.addItem(.separator())
      add("프로젝트 기록 다시 불러오기", to: menu, action: #selector(reloadLibrary))
    }
  }

  private func recentTitle(_ path: String) -> String {
    let abbreviated = (path as NSString).abbreviatingWithTildeInPath
    let title = String(
      abbreviated.map { character in
        character.unicodeScalars.contains(where: CharacterSet.controlCharacters.contains)
          ? Character(" ") : character
      })
    return title.count > 100 ? String(title.prefix(24)) + "…" + String(title.suffix(75)) : title
  }

  @discardableResult
  private func add(_ title: String, to menu: NSMenu, action: Selector) -> NSMenuItem {
    let item = menu.addItem(withTitle: title, action: action, keyEquivalent: "")
    item.target = self
    return item
  }

  private func placeholder(_ title: String, in menu: NSMenu) {
    let item = menu.addItem(withTitle: title, action: nil, keyEquivalent: "")
    item.isEnabled = false
  }

  @objc private func reloadLibrary() { load() }

  @objc private func clearRecent() {
    do { library = try store.update { $0.clearRecentProjects() } } catch {
      show(error, title: "최근 목록을 지우지 못했어요")
    }
  }

  @objc private func openRecent(_ sender: NSMenuItem) {
    guard let path = sender.representedObject as? String, directoryExists(path) else { return }
    manager.open(directory: path)
  }

  @objc private func openConfiguration(_ sender: NSMenuItem) {
    guard let value = sender.representedObject as? String,
      let entry = library.configurations.first(where: { $0.id.uuidString == value }),
      directoryExists(entry.projectDirectory)
    else { return }
    manager.open(configuration: entry)
  }

  private func directoryExists(_ path: String) -> Bool {
    var isDirectory: ObjCBool = false
    guard FileManager.default.fileExists(atPath: path, isDirectory: &isDirectory),
      isDirectory.boolValue
    else {
      let alert = NSAlert()
      alert.messageText = "프로젝트 폴더를 찾지 못했어요"
      alert.informativeText = "\(path)\n폴더 위치를 확인한 뒤 다시 열어 주세요."
      alert.addButton(withTitle: "확인")
      alert.runModal()
      return false
    }
    return true
  }

  @objc private func saveCurrent() {
    guard let controller = manager.active, controller.window?.attachedSheet == nil else { return }
    let field = InsetTextField(string: "")
    field.frame = NSRect(x: 0, y: 0, width: 300, height: 28)
    field.font = ChopStyle.font
    field.placeholderString = "구성 이름"
    field.setAccessibilityLabel("작업 구성 이름")
    let alert = NSAlert()
    alert.messageText = "작업 구성 저장"
    alert.informativeText = "배치와 폴더, 웹 주소를 저장해요. 실행 중인 명령은 저장하지 않아요."
    alert.accessoryView = field
    alert.addButton(withTitle: "취소").keyEquivalent = "\u{1b}"
    alert.addButton(withTitle: "저장").keyEquivalent = "\r"
    alert.window.initialFirstResponder = field
    while alert.runModal() == .alertSecondButtonReturn {
      do {
        let name = try ProjectLibrary.configurationName(field.stringValue)
        let current = try store.load()
        let existing = current.configuration(named: name, in: controller.projectDirectory)
        if let existing, !confirmReplacement(existing.name) { continue }
        library = try store.update {
          try $0.saveConfiguration(
            name: name, projectDirectory: controller.projectDirectory,
            workspace: controller.workspace.snapshot(),
            fileBrowser: controller.content.projectSettings,
            replacing: existing?.id)
        }
        break
      } catch { alert.informativeText = error.localizedDescription }
    }
    controller.workspace.focusedPane.focus()
  }

  private func confirmReplacement(_ name: String) -> Bool {
    let alert = NSAlert()
    alert.messageText = "‘\(name)’ 구성을 덮어쓸까요?"
    alert.informativeText = "저장한 배치와 폴더, 웹 주소가 현재 구성으로 바뀝니다."
    alert.addButton(withTitle: "취소")
    alert.addButton(withTitle: "덮어쓰기")
    return alert.runModal() == .alertSecondButtonReturn
  }

  @objc private func deleteConfiguration() {
    guard let controller = manager.active else { return }
    defer { controller.workspace.focusedPane.focus() }
    let entries = library.configurations(for: controller.projectDirectory)
    guard !entries.isEmpty else { return }
    let picker = NSPopUpButton(frame: NSRect(x: 0, y: 0, width: 300, height: 28))
    picker.font = ChopStyle.font
    picker.setAccessibilityLabel("삭제할 작업 구성")
    picker.addItems(withTitles: entries.map(\.name))
    let alert = NSAlert()
    alert.messageText = "작업 구성 삭제"
    alert.informativeText = "저장한 구성만 삭제해요. 열린 창과 프로젝트 파일은 유지됩니다."
    alert.accessoryView = picker
    alert.addButton(withTitle: "취소")
    alert.addButton(withTitle: "삭제")
    guard alert.runModal() == .alertSecondButtonReturn,
      entries.indices.contains(picker.indexOfSelectedItem)
    else { return }
    do {
      let entry = entries[picker.indexOfSelectedItem]
      library = try store.update {
        try $0.removeConfiguration(entry.id, in: controller.projectDirectory)
      }
    } catch { show(error, title: "작업 구성을 삭제하지 못했어요") }
  }

  func validateMenuItem(_ item: NSMenuItem) -> Bool {
    if item.action == #selector(clearRecent) { return !library.recentProjects.isEmpty }
    if item.action == #selector(saveCurrent) {
      return manager.active?.window?.isVisible == true
        && manager.active?.window?.attachedSheet == nil
    }
    if item.action == #selector(deleteConfiguration) {
      return manager.active.map { !library.configurations(for: $0.projectDirectory).isEmpty }
        ?? false
    }
    return true
  }

  private func show(_ error: Error, title: String) {
    let alert = NSAlert()
    alert.messageText = title
    alert.informativeText = "\(error.localizedDescription)\n\(store.fileURL.path)"
    alert.addButton(withTitle: "확인")
    alert.runModal()
  }
}

import AppKit
import ChopCore

@MainActor
final class WorkspaceWindowManager {
  private let engine: TerminalEngine
  private let defaultsForWindow: (UUID) -> UserDefaults
  private let clearDefaultsForWindow: (UUID) -> Void
  private(set) var windows: [UUID: WorkspaceWindowController] = [:]
  private var order: [UUID] = []
  private var focusedID: UUID?
  var onChange: (() -> Void)?
  var onAppearanceChangeRequested: ((AppearanceMode) -> Void)?
  var onProjectOpened: ((String) -> Void)?
  private(set) var cloneSheet: GitCloneSheet?
  private var preparingToTerminate = false

  var isCloningProject: Bool { cloneSheet?.isCloning == true }

  func prepareToTerminate() { preparingToTerminate = true }

  func requestClone() {
    guard !preparingToTerminate else { return }
    if let sheet = cloneSheet?.window {
      sheet.sheetParent?.makeKeyAndOrderFront(nil)
      sheet.makeKeyAndOrderFront(nil)
      return
    }
    let controller = active ?? open()
    guard let parent = controller.window, parent.attachedSheet == nil else { return }
    let saved = UserDefaults.standard.string(forKey: "cloneParentPath")
    let documents =
      FileManager.default.urls(for: .documentDirectory, in: .userDomainMask).first
      ?? FileManager.default.homeDirectoryForCurrentUser
    let directory = saved.map { URL(fileURLWithPath: $0, isDirectory: true) } ?? documents
    let sheet = GitCloneSheet(parentDirectory: directory)
    cloneSheet = sheet
    sheet.onFinish = { [weak self, weak controller] url in
      guard let self else { return }
      cloneSheet = nil
      guard !preparingToTerminate else { return }
      if let url {
        UserDefaults.standard.set(url.deletingLastPathComponent().path, forKey: "cloneParentPath")
        open(directory: url.path)
      } else {
        controller?.workspace.focusedPane.focus()
      }
    }
    sheet.present(for: parent)
  }

  func cancelClonesForTermination() async {
    preparingToTerminate = true
    let sheet = cloneSheet
    sheet?.cancel()
    await sheet?.waitForCompletion()
  }

  init(
    engine: TerminalEngine,
    clearDefaultsForWindow: @escaping (UUID) -> Void = {
      UserDefaults.standard.removePersistentDomain(
        forName: "com.safethecode.chop.window.\($0.uuidString)")
    },
    defaultsForWindow: @escaping (UUID) -> UserDefaults = {
      UserDefaults(suiteName: "com.safethecode.chop.window.\($0.uuidString)")!
    }
  ) {
    self.engine = engine
    self.defaultsForWindow = defaultsForWindow
    self.clearDefaultsForWindow = clearDefaultsForWindow
  }

  var active: WorkspaceWindowController? {
    for candidate in [NSApp.keyWindow, NSApp.mainWindow] {
      if let candidate, let controller = windows.values.first(where: { $0.window === candidate }) {
        return controller
      }
    }
    return focusedID.flatMap { windows[$0] } ?? order.last.flatMap { windows[$0] }
  }

  var needsConfirmClose: Bool { windows.values.contains { $0.workspace.needsConfirmClose } }

  @discardableResult
  func open(
    directory: String? = nil, snapshot: WorkspaceWindowSnapshot? = nil,
    legacyDefaults: UserDefaults? = nil, fileBrowser: ProjectFileBrowserSettings? = nil,
    recordVisit: Bool = true
  ) -> WorkspaceWindowController {
    let id = snapshot?.id ?? UUID()
    if let existing = windows[id] {
      activate(id)
      return existing
    }
    let path =
      snapshot?.projectDirectory ?? directory
      ?? FileManager.default.homeDirectoryForCurrentUser.path
    let defaults = defaultsForWindow(id)
    if let legacyDefaults {
      for key in ["fileTreeRootPath", "fileTreeVisible", "fileTreeWidth"] {
        if let value = legacyDefaults.object(forKey: key) { defaults.set(value, forKey: key) }
      }
    } else if defaults.object(forKey: "fileTreeRootPath") == nil {
      defaults.set(path, forKey: "fileTreeRootPath")
    }
    if let fileBrowser {
      defaults.set(fileBrowser.directory, forKey: "fileTreeRootPath")
      defaults.set(fileBrowser.isVisible, forKey: "fileTreeVisible")
      defaults.set(fileBrowser.width, forKey: "fileTreeWidth")
    }
    let controller = WorkspaceWindowController(
      engine: engine, id: id, snapshot: snapshot?.workspace, projectDirectory: path,
      defaults: defaults)
    let previous = active?.window
    windows[id] = controller
    order.append(id)
    controller.workspace.onChange = { [weak self] in self?.onChange?() }
    controller.workspace.onAppearanceChangeRequested = { [weak self] mode in
      self?.onAppearanceChangeRequested?(mode)
    }
    controller.workspace.onCloneRequested = { [weak self] in self?.requestClone() }
    controller.onActivate = { [weak self] in
      self?.focusedID = id
      self?.onChange?()
    }
    controller.onClose = { [weak self] in self?.remove(id) }
    if let frame = previous?.frame {
      controller.window?.cascadeTopLeft(from: NSPoint(x: frame.minX + 24, y: frame.maxY - 24))
    }
    activate(id)
    controller.workspace.layoutSubtreeIfNeeded()
    controller.workspace.startRestoredTerminals()
    if recordVisit { onProjectOpened?(path) }
    onChange?()
    return controller
  }

  @discardableResult
  func open(configuration: ProjectConfiguration) -> WorkspaceWindowController {
    open(
      snapshot: WorkspaceWindowSnapshot(
        id: UUID(), projectDirectory: configuration.projectDirectory,
        workspace: configuration.workspace), fileBrowser: configuration.fileBrowser)
  }

  func activate(_ id: UUID) {
    guard let controller = windows[id] else { return }
    focusedID = id
    controller.showWindow(nil)
    if controller.window?.isMiniaturized == true { controller.window?.deminiaturize(nil) }
    controller.window?.makeKeyAndOrderFront(nil)
  }

  private func remove(_ id: UUID) {
    guard let controller = windows.removeValue(forKey: id) else { return }
    order.removeAll { $0 == id }
    if focusedID == id { focusedID = order.last }
    clearDefaultsForWindow(id)
    let name = controller.windowFrameAutosaveName
    controller.windowFrameAutosaveName = ""
    NSWindow.removeFrame(usingName: name)
    onChange?()
  }

  func snapshot() -> ApplicationSnapshot {
    ApplicationSnapshot(
      windows: order.compactMap { id in
        guard let controller = windows[id] else { return nil }
        return WorkspaceWindowSnapshot(
          id: id, projectDirectory: controller.projectDirectory,
          workspace: controller.workspace.snapshot())
      }, focusedWindowID: active?.id)
  }

  func applyAppearance(_ mode: AppearanceMode) {
    for controller in windows.values { controller.workspace.applyAppearance(mode) }
  }

  func shutdown() {
    preparingToTerminate = true
    cloneSheet?.onFinish = nil
    cloneSheet?.cancel()
    cloneSheet = nil
    onChange = nil
    for controller in windows.values {
      controller.onClose = nil
      controller.onActivate = nil
      controller.workspace.closeAll()
      controller.window?.delegate = nil
      controller.window?.close()
    }
    windows.removeAll()
    order.removeAll()
    focusedID = nil
  }
}

import AppKit
import ChopCore

@MainActor
final class WorkspaceSplitView: NSSplitView, NSSplitViewDelegate {
  static let fileTreeMinimumWidth: CGFloat = 280
  private weak var workspace: WorkspaceView?
  private let canvas: NSView
  let fileBrowser: FileBrowserView
  var onMinimumSizeChange: ((CGSize) -> Void)?
  private let defaults: UserDefaults
  private var workspaceMinimum: CGSize
  private var browserWidth: CGFloat
  private var applying = false
  private var userResizing = false
  private var background = NSColor.white
  private var headerBackground = NSColor.white
  private(set) var isFileTreeVisible: Bool

  var projectSettings: ProjectFileBrowserSettings {
    ProjectFileBrowserSettings(
      directory: fileBrowser.rootURL.path, isVisible: isFileTreeVisible,
      width: Double(min(600, max(Self.fileTreeMinimumWidth, browserWidth))))
  }

  override var dividerThickness: CGFloat { isFileTreeVisible ? 1 : 0 }

  var minimumContentSize: CGSize {
    CGSize(
      width: max(
        640,
        isFileTreeVisible
          ? max(400, workspaceMinimum.width) + Self.fileTreeMinimumWidth + 1
          : workspaceMinimum.width),
      height: max(400, workspaceMinimum.height + 48))
  }

  init(workspace: WorkspaceView, canvas: NSView, defaults: UserDefaults = .standard) {
    self.workspace = workspace
    self.canvas = canvas
    self.defaults = defaults
    workspaceMinimum = workspace.displayMinimumSize
    let savedWidth = defaults.double(forKey: "fileTreeWidth")
    browserWidth =
      savedWidth.isFinite && savedWidth >= Self.fileTreeMinimumWidth
      ? min(600, savedWidth) : 300
    isFileTreeVisible =
      defaults.object(forKey: "fileTreeVisible") == nil
      ? true : defaults.bool(forKey: "fileTreeVisible")
    fileBrowser = FileBrowserView(
      initialURL: URL(fileURLWithPath: workspace.focusedPane.workingDirectory), defaults: defaults)
    super.init(frame: .zero)
    clipsToBounds = true
    isVertical = true
    dividerStyle = .thin
    delegate = self
    addArrangedSubview(canvas)
    addArrangedSubview(fileBrowser)
    applyAppearance(workspace.engine.appearanceMode)
    workspace.onMinimumSizeChange = { [weak self] size in
      guard let self else { return }
      workspaceMinimum = size
      refreshMinimumSize()
    }
    workspace.onFileTreeToggleRequested = { [weak self] in self?.toggleFileTree() }
    applyVisibility()
  }

  @available(*, unavailable)
  required init?(coder: NSCoder) { fatalError("Use init(workspace:canvas:defaults:).") }

  func refreshMinimumSize() {
    onMinimumSizeChange?(minimumContentSize)
    resizeSubviews(withOldSize: bounds.size)
    needsDisplay = true
  }

  func toggleFileTree() {
    if !isFileTreeVisible, !canFitFileTree {
      let alert = NSAlert()
      alert.messageText = "파일 트리를 열 공간이 부족해요"
      alert.informativeText = "터미널 칸을 줄이거나 더 넓은 디스플레이에서 열어 주세요."
      alert.addButton(withTitle: "확인")
      alert.runModal()
      workspace?.setFileTreeVisible(false)
      return
    }
    isFileTreeVisible.toggle()
    defaults.set(isFileTreeVisible, forKey: "fileTreeVisible")
    applyVisibility()
    workspace?.focusedPane.focus()
  }

  func showFileTree() {
    if !isFileTreeVisible { toggleFileTree() }
  }

  private var canFitFileTree: Bool {
    guard let screen = window?.screen else { return true }
    return max(400, workspaceMinimum.width) + Self.fileTreeMinimumWidth + 1
      <= screen.visibleFrame.width
  }

  override func viewDidMoveToWindow() {
    super.viewDidMoveToWindow()
    if isFileTreeVisible, !canFitFileTree {
      isFileTreeVisible = false
      applyVisibility()
    }
  }

  func applyAppearance(_ mode: AppearanceMode) {
    background = mode.background
    headerBackground = mode.headerBackground
    appearance = mode.appearance
    fileBrowser.applyAppearance(mode)
    needsDisplay = true
  }

  override var isOpaque: Bool { true }

  override func draw(_ dirtyRect: NSRect) {
    background.setFill()
    let clipped = dirtyRect.intersection(bounds)
    clipped.fill()
    super.draw(clipped)
  }

  override func drawDivider(in rect: NSRect) {
    guard isFileTreeVisible else { return }
    super.drawDivider(in: rect)
    // Continue the shared header surface across the functional resize divider.
    let height = min(ChopStyle.headerHeight, bounds.height)
    let header = NSRect(
      x: rect.minX, y: isFlipped ? bounds.minY : bounds.maxY - height,
      width: rect.width, height: height)
    headerBackground.setFill()
    header.intersection(rect).fill()
  }

  private func applyVisibility() {
    fileBrowser.isHidden = !isFileTreeVisible
    workspace?.setFileTreeVisible(isFileTreeVisible)
    refreshMinimumSize()
    needsDisplay = true
  }

  override func resizeSubviews(withOldSize oldSize: NSSize) {
    guard subviews.count == 2 else { return }
    applying = true
    defer { applying = false }
    guard isFileTreeVisible else {
      canvas.frame = bounds
      fileBrowser.frame = .zero
      return
    }
    let gap = min(dividerThickness, bounds.width)
    let available = max(0, bounds.width - gap)
    let minimumLeft = max(400, workspaceMinimum.width)
    let width =
      available >= minimumLeft + Self.fileTreeMinimumWidth
      ? min(max(Self.fileTreeMinimumWidth, browserWidth), available - minimumLeft)
      : min(browserWidth, available * 0.4)
    canvas.frame = NSRect(x: 0, y: 0, width: available - width, height: bounds.height)
    fileBrowser.frame = NSRect(
      x: available - width + gap, y: 0, width: width, height: bounds.height)
  }

  override func mouseDown(with event: NSEvent) {
    userResizing = true
    super.mouseDown(with: event)
    userResizing = false
    if isFileTreeVisible { defaults.set(browserWidth, forKey: "fileTreeWidth") }
  }

  func splitViewDidResizeSubviews(_ notification: Notification) {
    guard userResizing, !applying, isFileTreeVisible else { return }
    browserWidth = fileBrowser.frame.width
  }

  func splitView(
    _ splitView: NSSplitView, constrainMinCoordinate proposedMinimumPosition: CGFloat,
    ofSubviewAt dividerIndex: Int
  ) -> CGFloat { max(400, workspaceMinimum.width) }

  func splitView(
    _ splitView: NSSplitView, constrainMaxCoordinate proposedMaximumPosition: CGFloat,
    ofSubviewAt dividerIndex: Int
  ) -> CGFloat { bounds.width - Self.fileTreeMinimumWidth - dividerThickness }

  func splitView(_ splitView: NSSplitView, canCollapseSubview subview: NSView) -> Bool { false }
}

import Foundation

public struct ProjectFileBrowserSettings: Codable, Equatable, Sendable {
  public let directory: String
  public let isVisible: Bool
  public let width: Double

  public init(directory: String, isVisible: Bool, width: Double) {
    self.directory = directory
    self.isVisible = isVisible
    self.width = width
  }

  fileprivate func validate() throws {
    _ = try ProjectLibrary.projectPath(directory)
    guard width.isFinite, (280...600).contains(width) else { throw ProjectLibraryError.invalid }
  }
}

public struct ProjectConfiguration: Codable, Equatable, Sendable, Identifiable {
  public let id: UUID
  public let projectDirectory: String
  public let name: String
  public let workspace: WorkspaceSnapshot
  public let fileBrowser: ProjectFileBrowserSettings?
}

/// Reusable metadata, separate from the session's currently open windows and processes.
public struct ProjectLibrary: Codable, Equatable, Sendable {
  public var version = 1
  public private(set) var recentProjects: [String] = []
  public private(set) var configurations: [ProjectConfiguration] = []
  public static let maximumRecentProjects = 12
  public static let maximumConfigurationsPerProject = 20
  public static let maximumConfigurations = 100

  public init() {}

  public static func projectPath(_ path: String) throws -> String {
    guard path.hasPrefix("/"), path.utf8.count <= 4096, !path.contains("\0") else {
      throw ProjectLibraryError.invalid
    }
    return URL(fileURLWithPath: path, isDirectory: true).standardizedFileURL.path
  }

  public static func configurationName(_ value: String) throws -> String {
    let name = value.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !name.isEmpty, name.count <= 64,
      !name.unicodeScalars.contains(where: CharacterSet.controlCharacters.contains)
    else { throw ProjectLibraryError.invalidName }
    return name
  }

  private static func nameKey(_ name: String) -> String {
    name.folding(options: .caseInsensitive, locale: Locale(identifier: "en_US_POSIX"))
  }

  public func configurations(for directory: String) -> [ProjectConfiguration] {
    guard let path = try? Self.projectPath(directory) else { return [] }
    return configurations.filter { $0.projectDirectory == path }
      .sorted { $0.name.localizedStandardCompare($1.name) == .orderedAscending }
  }

  public func configuration(named name: String, in directory: String) -> ProjectConfiguration? {
    configurations(for: directory).first { Self.nameKey($0.name) == Self.nameKey(name) }
  }

  public mutating func visit(_ directory: String) throws {
    let path = try Self.projectPath(directory)
    recentProjects.removeAll { $0 == path }
    recentProjects.insert(path, at: 0)
    recentProjects = Array(recentProjects.prefix(Self.maximumRecentProjects))
  }

  public mutating func clearRecentProjects() { recentProjects.removeAll() }

  @discardableResult
  public mutating func saveConfiguration(
    name: String, projectDirectory: String, workspace: WorkspaceSnapshot,
    fileBrowser: ProjectFileBrowserSettings? = nil, replacing id: UUID? = nil
  ) throws -> UUID {
    let path = try Self.projectPath(projectDirectory)
    let name = try Self.configurationName(name)
    try workspace.validate()
    try fileBrowser?.validate()
    if configurations.contains(where: {
      $0.projectDirectory == path && Self.nameKey($0.name) == Self.nameKey(name) && $0.id != id
    }) {
      throw ProjectLibraryError.duplicateName
    }
    let index = id.flatMap { id in
      configurations.firstIndex { $0.id == id && $0.projectDirectory == path }
    }
    if id != nil, index == nil { throw ProjectLibraryError.missingConfiguration }
    if index == nil {
      guard configurations.count < Self.maximumConfigurations,
        configurations(for: path).count < Self.maximumConfigurationsPerProject
      else { throw ProjectLibraryError.limitReached }
    }
    let entry = ProjectConfiguration(
      id: id ?? UUID(), projectDirectory: path, name: name, workspace: workspace,
      fileBrowser: fileBrowser)
    if let index { configurations[index] = entry } else { configurations.append(entry) }
    return entry.id
  }

  public mutating func removeConfiguration(_ id: UUID, in directory: String) throws {
    let path = try Self.projectPath(directory)
    guard
      let index = configurations.firstIndex(where: {
        $0.id == id && $0.projectDirectory == path
      })
    else { throw ProjectLibraryError.missingConfiguration }
    configurations.remove(at: index)
  }

  public func validate() throws {
    guard version == 1 else { throw ProjectLibraryError.unsupportedVersion }
    guard recentProjects.count <= Self.maximumRecentProjects,
      Set(recentProjects).count == recentProjects.count,
      configurations.count <= Self.maximumConfigurations,
      Set(configurations.map(\.id)).count == configurations.count
    else { throw ProjectLibraryError.invalid }
    for path in recentProjects {
      guard try Self.projectPath(path) == path else { throw ProjectLibraryError.invalid }
    }
    var names: [String: Set<String>] = [:]
    for entry in configurations {
      guard try Self.projectPath(entry.projectDirectory) == entry.projectDirectory,
        try Self.configurationName(entry.name) == entry.name,
        names[entry.projectDirectory, default: []].insert(Self.nameKey(entry.name)).inserted,
        names[entry.projectDirectory]!.count <= Self.maximumConfigurationsPerProject
      else { throw ProjectLibraryError.invalid }
      try entry.workspace.validate()
      try entry.fileBrowser?.validate()
    }
  }
}

public enum ProjectLibraryError: LocalizedError {
  case invalid, invalidName, unsupportedVersion, duplicateName, missingConfiguration, limitReached
  case tooLarge, readFailed, writeFailed

  public var errorDescription: String? {
    switch self {
    case .invalid: return "프로젝트 기록의 형식이 올바르지 않아요. 기존 파일은 유지합니다."
    case .invalidName: return "이름을 줄바꿈 없이 1~64자로 입력해 주세요."
    case .unsupportedVersion: return "이 버전에서 읽을 수 없는 프로젝트 기록이에요. 기존 파일은 유지합니다."
    case .duplicateName: return "같은 이름의 작업 구성이 있어요."
    case .missingConfiguration: return "저장한 작업 구성을 찾지 못했어요. 목록을 다시 불러와 주세요."
    case .limitReached: return "작업 구성은 프로젝트마다 20개, 전체 100개까지 저장할 수 있어요. 사용하지 않는 구성을 삭제해 주세요."
    case .tooLarge: return "프로젝트 기록 파일이 너무 커요. 기존 파일은 유지합니다."
    case .readFailed: return "프로젝트 기록 파일을 읽지 못했어요. 기존 파일은 유지합니다."
    case .writeFailed: return "프로젝트 기록을 저장하지 못했어요. 저장 위치를 확인한 뒤 다시 시도해 주세요."
    }
  }
}

import Foundation

public struct ProjectLibraryStore: Sendable {
  public static let maximumBytes = 4 * 1024 * 1024
  public let fileURL: URL

  public init(fileURL: URL) { self.fileURL = fileURL }

  public func load() throws -> ProjectLibrary {
    guard FileManager.default.fileExists(atPath: fileURL.path) else { return ProjectLibrary() }
    let data: Data
    do {
      let size = try FileManager.default.attributesOfItem(atPath: fileURL.path)[.size] as? NSNumber
      guard size?.intValue ?? 0 <= Self.maximumBytes else { throw ProjectLibraryError.tooLarge }
      data = try Data(contentsOf: fileURL)
    } catch let error as ProjectLibraryError { throw error } catch {
      throw ProjectLibraryError.readFailed
    }
    guard data.count <= Self.maximumBytes else { throw ProjectLibraryError.tooLarge }
    let library: ProjectLibrary
    do { library = try JSONDecoder().decode(ProjectLibrary.self, from: data) } catch {
      throw ProjectLibraryError.invalid
    }
    do { try library.validate() } catch let error as ProjectLibraryError { throw error } catch {
      throw ProjectLibraryError.invalid
    }
    return library
  }

  /// Read and validate before every mutation: unreadable/newer records are never replaced.
  @discardableResult
  public func update(_ mutation: (inout ProjectLibrary) throws -> Void) throws -> ProjectLibrary {
    var library = try load()
    try mutation(&library)
    try library.validate()
    let encoder = JSONEncoder()
    encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
    let data = try encoder.encode(library)
    guard data.count <= Self.maximumBytes else { throw ProjectLibraryError.tooLarge }
    do {
      try FileManager.default.createDirectory(
        at: fileURL.deletingLastPathComponent(), withIntermediateDirectories: true,
        attributes: [.posixPermissions: 0o700])
      try data.write(to: fileURL, options: .atomic)
    } catch { throw ProjectLibraryError.writeFailed }
    return library
  }
}
